#!/usr/bin/env python3
# cartao.py (ficheiro unico): tem dentro o maquina.py, o arruma.py e o gera_nav.py.
# Faz tudo no cartao de uma vez:
#   1. maquina.py   em cada pasta de jogos (mete [48K], [128K]... no nome)
#   2. arruma.py    --por-titulo em cada pasta de jogos (letra \ titulo \ versoes)
#   3. gera_nav.py  no cartao todo (indices do navegador)
#
#   python cartao.py E:\            so' mostra o que faria
#   python cartao.py E:\ --fazer    faz
#   python cartao.py E:\ --so-indices --fazer   so' os indices (de todas as pastas), sem mexer nos nomes
#
# Pastas de jogos = as pastas da raiz do cartao, menos BIN, SYS, _NAV, FAVORITOS e as do
# sistema. Para escolher outras:  --pastas GAMES DEMOS
# Barra de baixo do navegador hi-res:  --pasta DEMOS GAMES PT3  (ou MUSICA/PT3=PT3)
#   ou no config.ini ao lado deste (secao [pastas]; ver mais abaixo)
# Nomes para o navegador normal de 32 colunas (sem hi-res):  --normal
# Este ficheiro ja' tem os outros tres dentro: basta ele.
import os, sys, argparse

AQUI = os.path.dirname(os.path.abspath(__file__))
FORA = {'BIN', 'SYS', '_NAV', 'FAVORITOS', 'TMP', 'SYSTEM VOLUME INFORMATION', '$RECYCLE.BIN', '__PYCACHE__'}

FONTES = {
    'maquina': '#!/usr/bin/env python3\n# Descobre para que maquina e\' cada ficheiro e mete-o no nome, estilo TOSEC:\n#   "Saboteur.z80"  ->  "Saboteur [48K].z80"\n#\n#   python3 maquina.py PASTA [--fazer] [--sem-subpastas]\n#   python3 maquina.py PASTA --forca TC2068 [--fazer]\n#       mete [TC2068] (ou a maquina que se disser) em todos os ficheiros da pasta que nao\n#       tem etiqueta ou so\' tem um palpite ([48K~], [128K~]); os que tem etiqueta certa ficam.\n#       Maquinas: 16K 48K 48K-AY 128K +2 +2A +3 TC2048 TC2068 TS2068 Pentagon Scorpion\n#\n# Sem --fazer so\' mostra o que faria. Ficheiros que ja\' tem uma etiqueta conhecida\n# no nome ([48K], [128K], (128K), [+3], ...) nao sao mexidos.\n#\n# Como decide:\n#   .z80  cabecalho (v1 = 48K; v2/v3 = byte "hardware mode")      -> certo\n#   .sna  tamanho (49179 = 48K; 131103/147487 = 128K)               -> certo\n#   .trd .scl                                                       -> 128K (TR-DOS)\n#   .dck                                                            -> TC2068\n#   .tzx  bloco 33h (tipo de hardware), se existir                  -> certo\n#   .tap e .tzx sem bloco 33h: palpite pelo codigo\n#         mais de 48K de dados                                      -> 128K\n#         codigo com "ld bc,7FFDh" (paginacao 128K)                 -> 128K?\n#         codigo com "ld bc,0FFFDh/0BFFDh" (AY)                     -> 48K-AY?\n#         nada disso                                                -> 48K?\n#   .z80 48K com o bit "AY em uso"                                  -> 48K-AY\n#   O "?" (no nome do ficheiro "~", ex. [48K~]) quer dizer palpite: um jogo 48K pode testar o 7FFD para tocar musica no 128.\nimport os, sys, re, struct, argparse\n\nETIQ = re.compile(r\'[\\[(](16K|48K(-AY)?[?~]?|128K[?~]?|\\+2A?|\\+3|Pentagon|Scorpion|TC2048|TC2068|TS2068|SamRam|Didaktik)[\\])]\', re.I)\n\nZ80_V2 = {0: \'48K\', 1: \'48K\', 2: \'SamRam\', 3: \'128K\', 4: \'128K\'}\nZ80_V3 = {0: \'48K\', 1: \'48K\', 2: \'SamRam\', 3: \'48K\', 4: \'128K\', 5: \'128K\', 6: \'128K\',\n          7: \'+3\', 8: \'+3\', 9: \'Pentagon\', 10: \'Scorpion\', 11: \'Didaktik\', 12: \'+2\',\n          13: \'+2A\', 14: \'TC2048\', 15: \'TC2068\', 128: \'TS2068\'}\n\ndef z80(d):\n    if len(d) < 30: return None\n    pc = struct.unpack(\'<H\', d[6:8])[0]\n    if pc != 0: return \'48K\'                         # v1\n    hl = struct.unpack(\'<H\', d[30:32])[0]\n    hw = d[34]\n    m = (Z80_V2 if hl == 23 else Z80_V3).get(hw)\n    if m and len(d) > 37 and d[37] & 0x80:           # bit 7: 48K->16K, 128K->+2, +3->+2A\n        m = {\'48K\': \'16K\', \'128K\': \'+2\', \'+3\': \'+2A\'}.get(m, m)\n    if m == \'48K\' and len(d) > 37 and d[37] & 0x04: m = \'48K-AY\'   # bit 2: AY em uso no 48K\n    return m\n\ndef sna(d):\n    return {49179: \'48K\', 131103: \'128K\', 147487: \'128K\'}.get(len(d))\n\n# AY num 48K: codigo com "ld bc,0FFFDh" ou "ld bc,0BFFDh"\ndef tem_ay(blocos):\n    return any(b\'\\x01\\xfd\\xff\' in b or b\'\\x01\\xfd\\xbf\' in b for b in blocos)\n\ndef palpite(blocos):\n    total = sum(len(b) for b in blocos)\n    if total > 49152 + 2048: return \'128K\'\n    # "ld a,10h/30h ; ld bc,7FFDh" so\' fixa a ROM 48 (o carregador do snapconv faz isto)\n    for b in blocos:\n        p = b.find(b\'\\x01\\xfd\\x7f\')\n        while p >= 0:\n            if not (p >= 2 and b[p-2] == 0x3e and b[p-1] in (0x10, 0x30)): return \'128K?\'\n            p = b.find(b\'\\x01\\xfd\\x7f\', p + 1)\n    return \'48K-AY?\' if tem_ay(blocos) else \'48K?\'\n\ndef tap(d):\n    blocos, i = [], 0\n    while i + 2 <= len(d):\n        n = struct.unpack(\'<H\', d[i:i+2])[0]\n        b = d[i+2:i+2+n]\n        if b[:1] == b\'\\xff\': blocos.append(b[1:-1])\n        i += 2 + n\n    return palpite(blocos)\n\n# tamanho do bloco a seguir ao identificador, para os blocos da TZX\ndef tzx(d):\n    if d[:7] != b\'ZXTape!\': return None\n    blocos, i, hw = [], 10, None\n    def u16(p): return struct.unpack(\'<H\', d[p:p+2])[0]\n    def u24(p): return d[p] | d[p+1] << 8 | d[p+2] << 16\n    def u32(p): return struct.unpack(\'<I\', d[p:p+4])[0]\n    while i < len(d):\n        t = d[i]; i += 1\n        if t == 0x10: n = u16(i+2); dados = d[i+4:i+4+n]; i += 4 + n\n        elif t == 0x11: n = u24(i+15); dados = d[i+18:i+18+n]; i += 18 + n\n        elif t == 0x14: n = u24(i+7); dados = d[i+10:i+10+n]; i += 10 + n\n        elif t == 0x12: i += 4; continue\n        elif t == 0x13: i += 1 + 2 * d[i]; continue\n        elif t == 0x15: i += 8 + u24(i+5); continue\n        elif t == 0x18 or t == 0x19: i += 4 + u32(i); continue\n        elif t == 0x20 or t == 0x23 or t == 0x24: i += 2; continue\n        elif t == 0x21 or t == 0x30: i += 1 + d[i]; continue\n        elif t == 0x22 or t == 0x25 or t == 0x27: continue\n        elif t == 0x26: i += 2 + 2 * u16(i); continue\n        elif t == 0x28 or t == 0x32: i += 2 + u16(i); continue\n        elif t == 0x2A: i += 4; continue\n        elif t == 0x2B: i += 5; continue\n        elif t == 0x31: i += 2 + d[i+1]; continue\n        elif t == 0x33:\n            # tipo 0 = computador; info 0 = corre, 1 = usa as capacidades especiais\n            nomes = {0: \'16K\', 1: \'48K\', 2: \'48K\', 3: \'128K\', 4: \'+2\', 5: \'+2A\', 6: \'TC2048\',\n                     7: \'TS2068\', 8: \'Pentagon\', 9: \'Scorpion\', 11: \'TC2068\', 18: \'Didaktik\'}\n            corre = []\n            for k in range(d[i]):\n                tipo, ident, info = d[i+1+3*k:i+4+3*k]\n                if tipo == 0 and info in (0, 1) and ident in nomes: corre.append(nomes[ident])\n            # se corre num 48K, e\' 48K; senao a primeira da lista\n            if corre: hw = \'48K\' if \'48K\' in corre else corre[0]\n            i += 1 + 3 * d[i]; continue\n        elif t == 0x35: i += 20 + u32(i+16); continue\n        elif t == 0x5A: i += 9; continue\n        else: break                                  # bloco desconhecido: pára\n        if dados[:1] == b\'\\xff\': blocos.append(dados[1:-1])\n    if hw == \'48K\' and tem_ay(blocos): hw = \'48K-AY\'\n    return hw or palpite(blocos)\n\nNAO_ETIQ = {\'.txt\', \'.py\', \'.idx\', \'.nfo\', \'.diz\', \'.jpg\', \'.jpeg\', \'.png\', \'.gif\', \'.pdf\', \'.doc\', \'.htm\', \'.html\', \'.md\'}\n\ndef maquina(caminho):\n    ext = os.path.splitext(caminho)[1].lower()\n    if ext in (\'.trd\', \'.scl\'): return \'128K\'\n    if ext == \'.dck\': return \'TC2068\'\n    if ext not in (\'.z80\', \'.sna\', \'.tap\', \'.tzx\'): return None\n    d = open(caminho, \'rb\').read()\n    return {\'.z80\': z80, \'.sna\': sna, \'.tap\': tap, \'.tzx\': tzx}[ext](d)\n\ndef main():\n    try: sys.stdout.reconfigure(errors=\'replace\')   # consola do Windows\n    except Exception: pass\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\'pasta\')\n    ap.add_argument(\'--fazer\', action=\'store_true\')\n    ap.add_argument(\'--sem-subpastas\', action=\'store_true\')\n    ap.add_argument(\'--forca\', metavar=\'MAQUINA\')\n    a = ap.parse_args()\n    if a.forca:\n        t = ETIQ.search(\'[%s]\' % a.forca)\n        if not t or \'?\' in a.forca or \'~\' in a.forca: sys.exit(\'maquina desconhecida: %s\' % a.forca)\n        a.forca = t.group(1)\n\n    conta = {}\n    for raiz, pastas, fichs in os.walk(a.pasta):\n        if a.sem_subpastas: pastas.clear()\n        pastas[:] = [p for p in pastas if p.upper() != \'_NAV\']\n        for f in sorted(fichs):\n            t = ETIQ.search(f)\n            base, ext = os.path.splitext(f)\n            if a.forca:\n                if ext.lower() in NAO_ETIQ or f.startswith(\'.\'): continue\n                if t and not t.group(1).endswith((\'?\', \'~\')): continue      # etiqueta certa: fica\n                if t: base = (base[:t.start()] + base[t.end():]).rstrip() if t.end() <= len(base) else base\n                m = a.forca\n            else:\n                if t: continue\n                try: m = maquina(os.path.join(raiz, f))\n                except Exception as e: print(\'ERRO\', f, e); continue\n                if not m: continue\n            # o Windows nao deixa \'?\' nos nomes: o palpite fica com \'~\' ([48K~])\n            novo = \'%s [%s]%s\' % (base, m.replace(\'?\', \'~\'), ext)\n            conta[m] = conta.get(m, 0) + 1\n            print(\'%-40s -> %s\' % (f, novo))\n            if a.fazer:\n                destino = os.path.join(raiz, novo)\n                if os.path.exists(destino): print(\'   ja existe, fica como esta\'); continue\n                os.rename(os.path.join(raiz, f), destino)\n\n    print(\', \'.join(\'%s: %d\' % kv for kv in sorted(conta.items())) or \'nada a mudar\')\n    if not a.fazer: print(\'(nada foi mudado; repete com --fazer)\')\n\nif __name__ == \'__main__\':\n    main()\n',
    'arruma': '#!/usr/bin/env python3\n# Arruma uma colecao grande ANTES de a copiar para o cartao: uma pasta por letra\n# e, dentro de cada letra, uma pasta por formato (o nome da extensao, qualquer que seja).\n#   GAMES\\Saboteur [48K].tap     ->  GAMES\\S\\TAP\\Saboteur [48K].tap\n#   GAMES\\3D Deathchase.z80      ->  GAMES\\0-9\\Z80\\3D Deathchase.z80\n#   GAMES\\The Great Escape.tap   ->  GAMES\\G\\TAP\\The Great Escape.tap   ("The/A/An" nao contam)\n#\n# Se a pasta ja\' estiver arrumada so\' por letra (GAMES\\S\\Saboteur.tap, da versao\n# anterior), os ficheiros de cada letra passam para a pasta do formato:\n#   GAMES\\S\\Saboteur [48K].tap   ->  GAMES\\S\\TAP\\Saboteur [48K].tap\n#\n#   python arruma.py D:\\sinclair\\Games D:\\sinclair\\Demos D:\\sinclair\\Apps          (so\' mostra)\n#   python arruma.py D:\\sinclair\\Games D:\\sinclair\\Demos D:\\sinclair\\Apps --fazer  (move)\n#\n# Se uma letra\\formato ficar com mais de 300 ficheiros, parte-se pelas 2 primeiras letras:\n#   GAMES\\S\\TAP\\SA\\Saboteur [48K].tap , GAMES\\S\\TAP\\SP\\Spellbound.tap ...\n#\n# Varios ficheiros do mesmo titulo (lados, partes, versoes) no mesmo formato ficam juntos\n# numa pasta com o nome do titulo (sem o que esta\' entre [] ou () nem "side A", "part 2"...):\n#   GAMES\\S\\TAP\\Saboteur (side A).tap , Saboteur (side B).tap -> GAMES\\S\\TAP\\Saboteur\\...\n# Se essa pasta ja\' existir, os novos ficheiros desse titulo tambem vao para la\'.\n#\n# Opcoes:  --max N         outro limite (0 = nunca partir em 2 letras)\n#          --so-letra      so\' pastas por letra, sem formatos\n#          --sem-titulos   nao fazer as pastas por titulo\n#          --por-titulo    outra arrumacao: so\' letra e titulo, com os formatos juntos:\n#                            GAMES\\S\\Saboteur\\Saboteur.tap , Saboteur [128K].z80 , ...\n#                            GAMES\\S\\Spellbound.tap          (titulo com um so\' ficheiro: solto)\n#                          Uma letra com mais de --max titulos parte-se pelas 2 primeiras letras.\n#                          Converte tambem o que ja\' estava por letra\\formato (as pastas que\n#                          ficam vazias apagam-se).\n# So\' move ficheiros (nunca apaga). Pastas so\' sao criadas se houver ficheiros.\n# Pode correr-se varias vezes: o que ja\' esta\' no sitio fica.\n# Ordem: maquina.py --fazer  ->  arruma.py --fazer  ->  copiar para o cartao  ->  gera_nav.py no cartao.\nimport os, sys, re, argparse, shutil\n\nNAO_MEXER = {\'.py\', \'.txt\', \'.idx\'}\nLETRAS = {\'0-9\', \'#\'} | {chr(c) for c in range(ord(\'A\'), ord(\'Z\') + 1)}\n\ndef letra(nome):\n    n = re.sub(r\'^(the|a|an)[ _-]+\', \'\', nome.lower())        # como no gera_nav.py\n    n = re.sub(r\'[^a-z0-9]\', \'\', n)\n    if not n: return \'#\'\n    if n[0].isdigit(): return \'0-9\'\n    return n[0].upper()\n\ndef formato(nome):                                   # a pasta e\' a extensao: .tap -> TAP, .pt3 -> PT3\n    e = os.path.splitext(nome)[1][1:].upper()\n    e = re.sub(r\'[^A-Z0-9_-]\', \'_\', e)\n    return e or \'SEM_EXT\'\n\ndef ficheiros(pasta):\n    return [f for f in sorted(os.listdir(pasta)) if os.path.isfile(os.path.join(pasta, f))\n            and not f.startswith(\'.\') and os.path.splitext(f)[1].lower() not in NAO_MEXER]\n\ndef titulo(nome):                                    # "Saboteur (side A) [48K].tap" -> "Saboteur"\n    b = os.path.splitext(nome)[0]\n    b = re.sub(r\'[\\[\\(\\{][^\\]\\)\\}]*[\\]\\)\\}]\', \' \', b)\n    b = re.sub(r\'(?i)[\\s_-]+(side|lado|part|parte|disk|disco|tape|cassete|cassette|block|bloco)[\\s_-]*[0-9a-d]{1,2}\\b.*$\', \'\', b)\n    b = re.sub(r\'[<>:"/\\\\|?*~]\', \'_\', b)\n    b = re.sub(r\'\\s+\', \' \', b).strip(\' ._-\')\n    return b[:40].rstrip(\' .\') or None\n\ndef letra2(nome):                                    # duas primeiras letras: "Saboteur" -> SA\n    n = re.sub(r\'^(the|a|an)[ _-]+\', \'\', nome.lower())\n    n = re.sub(r\'[^a-z0-9]\', \'\', n).upper()\n    return (n + \'__\')[:2] if n else \'__\'\n\ndef vazia(d):                                         # so\' tem um _NAV (indices) ou nada\n    try: e = os.listdir(d)\n    except OSError: return False\n    return all(x.upper() == \'_NAV\' and os.path.isdir(os.path.join(d, x)) for x in e)\n\ndef por_titulo(pasta, a):\n    cand = [(os.path.join(pasta, f), letra(f)) for f in ficheiros(pasta)]\n    for d in sorted(os.listdir(pasta)):\n        dl = os.path.join(pasta, d)\n        if d.upper() not in LETRAS or not os.path.isdir(dl): continue\n        for raiz, subs, fs in os.walk(dl):\n            subs[:] = [x for x in subs if x.upper() != \'_NAV\']\n            cand += [(os.path.join(raiz, f), d) for f in ficheiros(raiz)]\n    grupos = {}\n    for c in cand: grupos.setdefault(c[1], []).append(c)\n    mover, partidas = [], 0\n    for le, lista in sorted(grupos.items()):\n        nt, nome_t = {}, {}\n        for orig, _ in lista:\n            t = titulo(os.path.basename(orig)) or os.path.splitext(os.path.basename(orig))[0]\n            k = t.lower(); nt[k] = nt.get(k, 0) + 1; nome_t.setdefault(k, t)\n        partir = a.max and len(nt) > a.max\n        partidas += bool(partir)\n        for orig, _ in lista:\n            t = titulo(os.path.basename(orig)) or os.path.splitext(os.path.basename(orig))[0]\n            k = t.lower()\n            sub = [le] + ([letra2(nome_t[k])] if partir else []) + ([nome_t[k]] if nt[k] >= 2 else [])\n            dest_dir = os.path.join(pasta, *sub)\n            if os.path.normcase(os.path.dirname(orig)) != os.path.normcase(dest_dir):\n                mover.append((orig, dest_dir))\n    feitos = 0\n    for orig, dest_dir in mover:\n        if a.fazer:\n            os.makedirs(dest_dir, exist_ok=True)\n            dest = os.path.join(dest_dir, os.path.basename(orig))\n            if os.path.exists(dest): print(\'   ja existe, fica:\', orig); continue\n            shutil.move(orig, dest); feitos += 1\n    apagadas = 0\n    if a.fazer:                                       # pastas que ficaram vazias (ou so\' com _NAV)\n        for d in sorted(os.listdir(pasta)):\n            dl = os.path.join(pasta, d)\n            if d.upper() not in LETRAS or not os.path.isdir(dl): continue\n            for raiz, subs, fs in os.walk(dl, topdown=False):\n                if os.path.basename(raiz).upper() == \'_NAV\': continue\n                if raiz != dl and vazia(raiz):\n                    shutil.rmtree(raiz); apagadas += 1\n    print(pasta)\n    print(\'   %d ficheiros a mover%s\' % (len(mover), (\' (%d movidos, %d pastas vazias apagadas)\' % (feitos, apagadas)) if a.fazer else \'\'))\n    if partidas: print(\'   %d letras com mais de %d titulos partidas pelas 2 primeiras letras\' % (partidas, a.max))\n\ndef main():\n    try: sys.stdout.reconfigure(errors=\'replace\')\n    except Exception: pass\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\'pastas\', nargs=\'+\')\n    ap.add_argument(\'--fazer\', action=\'store_true\')\n    ap.add_argument(\'--so-letra\', action=\'store_true\')\n    ap.add_argument(\'--sem-titulos\', action=\'store_true\')\n    ap.add_argument(\'--por-titulo\', action=\'store_true\')\n    ap.add_argument(\'--max\', type=int, default=300,\n                    help=\'pasta letra/formato com mais do que isto parte-se pelas 2 primeiras letras (0 = nunca)\')\n    a = ap.parse_args()\n    for pasta in a.pastas:\n        if not os.path.isdir(pasta):\n            print(\'nao existe:\', pasta); continue\n        if a.por_titulo:\n            por_titulo(pasta, a); continue\n        # (origem, letra, formato): soltos na pasta, soltos numa letra, soltos numa letra\\formato\n        cand = [(os.path.join(pasta, f), letra(f), formato(f)) for f in ficheiros(pasta)]\n        for d in sorted(os.listdir(pasta)):\n            dl = os.path.join(pasta, d)\n            if d.upper() not in LETRAS or not os.path.isdir(dl): continue\n            cand += [(os.path.join(dl, f), d, formato(f)) for f in ficheiros(dl)]\n            if a.so_letra: continue\n            for fm in sorted(os.listdir(dl)):\n                dfm = os.path.join(dl, fm)\n                if os.path.isdir(dfm):\n                    cand += [(os.path.join(dfm, f), d, fm) for f in ficheiros(dfm)]\n        grupos = {}\n        for c in cand:\n            grupos.setdefault((c[1], None if a.so_letra else c[2]), []).append(c)\n        mover, partidas = [], 0\n        for (le, fm), lista in sorted(grupos.items()):\n            partir = not a.so_letra and a.max and len(lista) > a.max\n            partidas += bool(partir)\n            nt, nome_t = {}, {}                      # quantos ficheiros por titulo (e o nome da pasta)\n            for orig, _, _ in lista:\n                t = titulo(os.path.basename(orig))\n                if t:\n                    k = (letra2(os.path.basename(orig)) if partir else \'\', t.lower())\n                    nt[k] = nt.get(k, 0) + 1; nome_t.setdefault(k, t)\n            for orig, _, _ in lista:\n                sub = [le] + ([fm] if fm else []) + ([letra2(os.path.basename(orig))] if partir else [])\n                t = None if a.sem_titulos else titulo(os.path.basename(orig))\n                if t:\n                    k = (letra2(os.path.basename(orig)) if partir else \'\', t.lower())\n                    def acha(rel):                   # pasta deste titulo que ja\' exista em rel\n                        base = os.path.join(pasta, *rel)\n                        for d in (os.listdir(base) if os.path.isdir(base) else []):\n                            if d.lower() == t.lower() and os.path.isdir(os.path.join(base, d)): return rel + [d]\n                    l2 = sub + [letra2(os.path.basename(orig))]   # pode estar dentro da pasta das 2 letras\n                    existe = acha(sub) or (None if partir else acha(l2))\n                    if existe: sub = existe\n                    elif nt[k] >= 2: sub.append(nome_t[k])\n                dest_dir = os.path.join(pasta, *sub)\n                if os.path.normcase(os.path.dirname(orig)) != os.path.normcase(dest_dir):\n                    mover.append((orig, dest_dir))\n        contagem = {}\n        for orig, dest_dir in mover:\n            rel = os.path.relpath(dest_dir, pasta)\n            contagem[rel] = contagem.get(rel, 0) + 1\n            if a.fazer:\n                os.makedirs(dest_dir, exist_ok=True)\n                dest = os.path.join(dest_dir, os.path.basename(orig))\n                if os.path.exists(dest): print(\'   ja existe, fica:\', orig); continue\n                shutil.move(orig, dest)\n        print(pasta)\n        if not contagem:\n            print(\'   nada a mudar\'); continue\n        maior = max(contagem, key=contagem.get)\n        print(\'   %d ficheiros a mover para %d pastas (a maior: %s com %d)\' % (len(mover), len(contagem), maior, contagem[maior]))\n        if partidas: print(\'   %d pastas letra/formato com mais de %d partidas pelas 2 primeiras letras\' % (partidas, a.max))\n        if not a.so_letra:\n            por_formato = {}\n            for rel, n in contagem.items():\n                fm = rel.split(os.sep)[1]\n                por_formato[fm] = por_formato.get(fm, 0) + n\n            print(\'   \' + \', \'.join(\'%s %d\' % kv for kv in sorted(por_formato.items())))\n    if not a.fazer: print(\'(nada foi mudado; repete com --fazer)\')\n\nif __name__ == \'__main__\':\n    main()\n',
    'gera_nav': '#!/usr/bin/env python3\n# Cria os indices do navegador (_NAV/*.IDX) em cada pasta do cartao SD.\n# Junta, para cada ficheiro: nome grande, nome 8.3 (o que os plugins precisam) e maquina.\n#\n#   python3 gera_nav.py /run/media/$USER/SD/GAMES [/run/media/$USER/SD/DEMOS ...]\n#   Windows:  py gera_nav.py E:\\    (E: = letra do cartao)\n#   --pasta DEMOS GAMES MUSICA/PT3=PT3   pastas da barra de baixo do navegador hi-res\n#              (nome ou caminho dentro do cartao; "=NOME" e\' o que aparece: [PT3])\n#   --largura 17   nomes para o navegador normal (32 colunas); por defeito 46 (hi-res)\n#\n# Tem de ser o cartao montado (FAT/vfat): o nome 8.3 vem do proprio Linux\n# (ioctl VFAT_IOCTL_READDIR_BOTH), que da\' o nome curto tal como esta\' gravado.\n# Corre tambem nas subpastas. Sem --fazer so\' mostra o que faria.\n#\n# Formato (tudo little-endian):\n#   _NAV/NAV.IDX   "NAV1", u16 total de entradas, u16 reservado,\n#                  29 x u16: quantos ha\' em DIR, 0-9, A..Z, outros\n#                  6 x 29 x u16: o mesmo, so\' para cada maquina (0..5, como no byte 0 abaixo)\n#   _NAV/DIR.IDX, 0.IDX, A.IDX ... Z.IDX, _.IDX   registos de 64 bytes, ordenados:\n#     0      maquina: 0 desconhecida, 1 48K, 2 48K+AY, 3 128K, 4 Timex, 5 outra\n#            (+3, Pentagon...); bit 7 = palpite\n#     1      0 ficheiro, 1 pasta\n#     2-3    reservado\n#     4-16   nome 8.3, terminado em 0 (ex. "GHOSTS~1.TAP")\n#     17-63  nome grande sem a etiqueta da maquina, ASCII, terminado em 0 (46 letras no maximo)\nimport os, sys, re, struct, ctypes, argparse, unicodedata\nif os.name != \'nt\':\n    import fcntl\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport maquina as mq\n\n# struct __fat_dirent { long d_ino; __kernel_off_t d_off; unsigned short d_reclen; char d_name[256]; }\nclass FatDirent(ctypes.Structure):\n    _fields_ = [(\'d_ino\', ctypes.c_long), (\'d_off\', ctypes.c_long),\n                (\'d_reclen\', ctypes.c_ushort), (\'d_name\', ctypes.c_char * 256)]\nPar = FatDirent * 2\ndef _IOR(t, n, size): return (2 << 30) | (size << 16) | (ord(t) << 8) | n\nVFAT_IOCTL_READDIR_BOTH = _IOR(\'r\', 1, ctypes.sizeof(Par))\n\ndef ler_pasta_linux(caminho):\n    """[(nome grande, nome 8.3, e\' pasta)] pela ordem do disco"""\n    fd = os.open(caminho, os.O_RDONLY | os.O_DIRECTORY)\n    out = []\n    try:\n        while True:\n            d = Par()\n            r = fcntl.ioctl(fd, VFAT_IOCTL_READDIR_BOTH, d)\n            if r <= 0 or d[0].d_reclen == 0: break\n            curto = d[0].d_name[:d[0].d_reclen].decode(\'latin-1\')\n            grande = d[1].d_name[:d[1].d_reclen].decode(\'utf-8\', \'replace\') if d[1].d_reclen else curto\n            if curto in (\'.\', \'..\'): continue\n            pasta = os.path.isdir(os.path.join(caminho, grande))\n            out.append((grande, curto.upper(), pasta))\n    finally:\n        os.close(fd)\n    return out\n\n# Windows: o nome 8.3 vem de GetShortPathNameW (no FAT32 o Windows grava sempre o nome curto)\ndef ler_pasta_windows(caminho):\n    from ctypes import wintypes\n    f = ctypes.windll.kernel32.GetShortPathNameW\n    f.argtypes = [wintypes.LPCWSTR, wintypes.LPWSTR, wintypes.DWORD]\n    f.restype = wintypes.DWORD\n    out = []\n    for grande in os.listdir(caminho):\n        cheio = os.path.join(caminho, grande)\n        buf = ctypes.create_unicode_buffer(1024)\n        n = f(cheio, buf, 1024)\n        curto = os.path.basename(buf.value) if n else grande\n        out.append((grande, curto.upper(), os.path.isdir(cheio)))\n    return out\n\ndef ler_pasta(caminho):\n    return ler_pasta_windows(caminho) if os.name == \'nt\' else ler_pasta_linux(caminho)\n\nGRUPOS = [\'DIR\', \'0\'] + [chr(c) for c in range(65, 91)] + [\'_\']\n\ndef chave(nome):\n    n = re.sub(r\'^(the|a|an)[ _-]+\', \'\', nome.lower())\n    return re.sub(r\'[^a-z0-9]\', \'\', n) or \'_\'\n\ndef grupo(nome, pasta):\n    # pastas de arrumacao (A..Z, 0-9, #, as de 2 letras, FAVORITOS/GAMES/...) ficam em DIR;\n    # as outras (titulos, colecoes) entram na letra delas, no meio dos ficheiros\n    if pasta and (len(nome) <= 2 or nome.upper() in (\'0-9\', \'#\') or nome.upper() in PRIMEIRO): return 0\n    c = chave(nome)[0]\n    if c.isdigit(): return 1\n    if \'a\' <= c <= \'z\': return 2 + ord(c) - 97\n    return 28\n\nCOD = {\'48K\': 1, \'16K\': 1, \'48K-AY\': 2, \'128K\': 3, \'+2\': 3, \'TC2048\': 4, \'TC2068\': 4, \'TS2068\': 4}\ndef codigo(m):\n    if not m: return 0\n    palp = m.endswith((\'?\', \'~\')); m = m.rstrip(\'?~\')\n    return COD.get(m.upper(), 5) | (0x80 if palp else 0)\n\ndef ascii_spectrum(s):\n    s = unicodedata.normalize(\'NFKD\', s).encode(\'ascii\', \'ignore\').decode()\n    return \'\'.join(c if 32 <= ord(c) < 127 else \'?\' for c in s)\n\nLARG_NOME = 46      # letras do nome na lista: 46 no hi-res (64 colunas), 17 no normal (32)\ndef registo(grande, curto, pasta, cod):\n    vis = mq.ETIQ.sub(\'\', os.path.splitext(grande)[0] if not pasta else grande)\n    vis = re.sub(r\'\\s+\', \' \', vis).strip()\n    ext = \'\' if pasta else os.path.splitext(grande)[1].lower()\n    vis = ascii_spectrum(vis)\n    ext = ascii_spectrum(ext)\n    # comprido demais: primeiro tira os (ano)(editora)... do fim, menos lados/partes\n    while len(vis) + len(ext) > LARG_NOME:\n        m = re.search(r\'\\s*[\\(\\[]([^\\(\\)\\[\\]]*)[\\)\\]]\\s*$\', vis)\n        if not m or re.search(r\'(?i)\\b(side|lado|part|parte|disk|disco|tape|cassete|cassette|block|bloco)\\b\', m.group(1)): break\n        vis = vis[:m.start()].rstrip()\n    if len(vis) + len(ext) > LARG_NOME and len(ext) < LARG_NOME - 4:\n        # o navegador so\' mostra LARG_NOME letras: corta o nome e deixa a extensao a\' vista\n        # e o fim do nome tambem (lados e partes: "Head ov~Part 1.tap" / "Head ov~Part 2.tap")\n        livre = LARG_NOME - len(ext) - 1\n        ini = (livre + 1) // 2\n        vis = vis[:ini].rstrip() + \'~\' + vis[len(vis) - (livre - ini):].lstrip()\n    vis = (vis + ext)[:46]\n    r = bytearray(64)\n    r[0] = cod; r[1] = 1 if pasta else 0\n    c = curto.encode(\'ascii\', \'replace\')[:12]      # 8.3 tem no maximo 12 letras\n    v = vis.encode()[:46]\n    r[4:4 + len(c)] = c                             # o mesmo tamanho dos dois lados: o registo fica com 64\n    r[17:17 + len(v)] = v\n    assert len(r) == 64\n    return bytes(r)\n\nMUSICA = {\'.pt3\', \'.pt2\', \'.pt1\', \'.stc\', \'.sqt\', \'.stp\', \'.psc\', \'.ftc\', \'.fxm\', \'.ay\', \'.mym\'}\nPRIMEIRO = [\'FAVORITOS\', \'GAMES\', \'APPS\', \'DEMOS\']\n\n# pastas de sistema: nao se indexam nem aparecem no navegador\nSISTEMA = {\'_NAV\', \'BIN\', \'SYS\', \'TMP\', \'SYSTEM VOLUME INFORMATION\', \'$RECYCLE.BIN\'}\ndef de_sistema(nome, topo=True):                    # BIN, SYS... so\' contam na raiz (GAMES\\S\\BIN e\' um formato)\n    return nome.upper() == \'_NAV\' or nome.startswith(\'.\') or (topo and nome.upper() in SISTEMA)\n\n# So\' entram no indice os ficheiros que o navegador consegue correr: os que tem plugin em\n# /BIN/BPLUGINS do cartao. Sem essa pasta, a lista dos plugins do Bob Fossil que funcionam\n# num Spectrum/Timex com DivMMC (sem os so\' de ZX-UNO: PZX, WAV, RAD). TZX nao tem plugin.\nPLUGINS_BOB = {\'TAP\', \'Z80\', \'SNA\', \'TRD\', \'SCL\', \'BAS\', \'ROM\', \'POK\',\n               \'PT1\', \'PT2\', \'PT3\', \'SQT\', \'STC\', \'STP\', \'FXM\', \'FTC\', \'PSC\', \'MYM\', \'AY\', \'MID\',\n               \'SCR\', \'LCE\', \'IMG\', \'MG1\', \'MG2\', \'MG4\', \'ART\', \'IPH\', \'HAM\', \'ULA\', \'TXT\'}\nCORRE = None                                         # None = todos (--todos)\n\ndef plugins_do_cartao(p):\n    d = os.path.abspath(p)\n    while True:                                      # sobe ate\' encontrar BIN/BPLUGINS\n        for b in (\'BIN\', \'bin\'):\n            pl = os.path.join(d, b, \'BPLUGINS\')\n            if not os.path.isdir(pl): pl = os.path.join(d, b, \'bplugins\')\n            if os.path.isdir(pl):\n                return {f.upper() for f in os.listdir(pl)\n                        if os.path.isfile(os.path.join(pl, f)) and \'.\' not in f}, pl\n        cima = os.path.dirname(d)\n        if cima == d: return None, None\n        d = cima\n\n# A maquina escolhida no navegador e\' tambem a lista que se ve (byte 0 do registo:\n# 0 ?, 1 48K, 2 48K+AY, 3 128K, 4 Timex, 5 outra):\n#   1 Timex 48  : Timex, 48K, 48K+AY e desconhecidos\n#   2 ZX 48K    : 48K, 48K+AY e desconhecidos\n#   3 ZX 128K   : 128K e outras\n#   4 Timex 128 : 128K e Timex\n#   5 TC2068    : Timex (o NAV nao corre no TC2068: sem NMI)\nVISTAS = {1: (0, 1, 2, 4), 2: (0, 1, 2), 3: (3, 5), 4: (3, 4), 5: (4,)}\ndef na_vista(b0, v):\n    if v == 0: return True\n    return (b0 & 0x7f) in VISTAS.get(v, ())\n\ndef corre(nome, ehpasta):\n    if ehpasta or CORRE is None: return True\n    return os.path.splitext(nome)[1][1:].upper() in CORRE\n\ndef processa(pasta, fazer, topo=True):\n    lidas = [e for e in ler_pasta(pasta) if not de_sistema(e[0], topo) and e[1] != \'_NAV\']\n    entradas = [e for e in lidas if corre(e[0], e[2])]\n    fora = len(lidas) - len(entradas)\n    grupos = [[] for _ in GRUPOS]\n    for grande, curto, ehpasta in entradas:\n        m = None\n        if not ehpasta:\n            t = mq.ETIQ.search(grande)\n            m = t.group(1) if t else None\n            if not m:\n                try: m = mq.maquina(os.path.join(pasta, grande))\n                except Exception: m = None\n                if not m and os.path.splitext(grande)[1].lower() in MUSICA:\n                    m = \'48K-AY\'                     # musica do chip AY: etiqueta AY no navegador\n        k = chave(grande)\n        if ehpasta and grande.upper() in PRIMEIRO:      # FAVORITOS, GAMES, APPS, DEMOS sempre no topo\n            k = \'\\x00%d\' % PRIMEIRO.index(grande.upper())\n        grupos[grupo(grande, ehpasta)].append((k, registo(grande, curto, ehpasta, codigo(m))))\n    nav = b\'NAV1\' + struct.pack(\'<HH\', len(entradas), 0) + b\'\'.join(struct.pack(\'<H\', len(g)) for g in grupos)\n    # contagens por vista (a maquina escolhida no navegador): 6 tabelas de 29 x u16,\n    # 0 = todos, 1..4 = VISTAS, 5 = nao usada\n    for v in range(6):\n        nav += b\'\'.join(struct.pack(\'<H\', sum(1 for _, r in g if na_vista(r[0], v))) for g in grupos)\n    print(\'%s: %d entradas%s  \' % (pasta, len(entradas), \' (%d sem plugin, fora)\' % fora if fora else \'\') +\n          \' \'.join(\'%s:%d\' % (GRUPOS[i], len(g)) for i, g in enumerate(grupos) if g))\n    if not fazer: return\n    d = os.path.join(pasta, \'_NAV\')\n    os.makedirs(d, exist_ok=True)\n    for i, g in enumerate(grupos):\n        g.sort(key=lambda x: x[0])\n        # So\' o X.IDX (todos): o navegador mostra sempre tudo. Os X1..X5.IDX de versoes\n        # anteriores apagam-se.\n        for filtro in range(6):\n            f = os.path.join(d, GRUPOS[i] + (\'%d\' % filtro if filtro else \'\') + \'.IDX\')\n            sel = g if filtro == 0 else []\n            if sel:\n                open(f, \'wb\').write(b\'\'.join(r for _, r in sel))\n            elif os.path.exists(f):\n                os.remove(f)\n    open(os.path.join(d, \'NAV.IDX\'), \'wb\').write(nav)\n\n# /_NAV/PASTAS.IDX na raiz do cartao: ate\' 8 registos de 64 bytes:\n#   0-7  nome (ate\' 6 letras, o que aparece na barra: [DEMOS])\n#   8-63 caminho 8.3 a partir da raiz ("/MUSICA/PT3"), terminado em 0\ndef caminho_curto(raiz, rel):\n    partes = [p for p in re.split(r\'[\\\\/]\', rel) if p]\n    cur, curto = raiz, \'\'\n    for p in partes:\n        ach = [e for e in ler_pasta(cur) if e[2] and e[0].lower() == p.lower()]\n        if not ach: return None\n        cur = os.path.join(cur, ach[0][0]); curto += \'/\' + ach[0][1]\n    return curto\n\ndef procura_pasta(raiz, nome):\n    if \'/\' in nome or \'\\\\\' in nome:\n        return nome if os.path.isdir(os.path.join(raiz, nome)) else None\n    achadas = []\n    for d, subs, _ in os.walk(raiz):\n        subs[:] = sorted(x for x in subs if not de_sistema(x, os.path.normpath(d) == os.path.normpath(raiz)))\n        for x in subs:\n            if x.lower() == nome.lower():\n                achadas.append(os.path.relpath(os.path.join(d, x), raiz))\n    achadas.sort(key=lambda r: (r.count(os.sep), r.lower()))      # a menos funda\n    return achadas[0] if achadas else None\n\ndef escreve_pastas(raiz, pedidas, fazer):\n    regs = []\n    for p in pedidas:\n        nome, _, rot = p.partition(\'=\')\n        rel = procura_pasta(raiz, nome)\n        if not rel: print(\'pasta %s: nao encontrei no cartao\' % nome); continue\n        curto = caminho_curto(raiz, rel)\n        rot = ascii_spectrum(rot or os.path.basename(rel)).upper()[:6]\n        if not curto or len(curto) > 55: print(\'pasta %s: caminho 8.3 comprido demais\' % nome); continue\n        print(\'pasta [%s] = %s (%s)\' % (rot, rel, curto))\n        r = bytearray(64); r[0:len(rot)] = rot.encode(); r[8:8 + len(curto)] = curto.encode(\'ascii\', \'replace\')\n        regs.append(bytes(r))\n    if len(regs) > 8: print(\'so\\\' cabem 8 pastas na barra: fico com as 8 primeiras\'); regs = regs[:8]\n    if not fazer: return\n    d = os.path.join(raiz, \'_NAV\'); os.makedirs(d, exist_ok=True)\n    f = os.path.join(d, \'PASTAS.IDX\')\n    if regs: open(f, \'wb\').write(b\'\'.join(regs))\n    elif os.path.exists(f): os.remove(f)\n\ndef main():\n    try: sys.stdout.reconfigure(errors=\'replace\')   # consola do Windows\n    except Exception: pass\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\'pastas\', nargs=\'+\')\n    ap.add_argument(\'--fazer\', action=\'store_true\')\n    ap.add_argument(\'--todos\', action=\'store_true\', help=\'indexa tambem os ficheiros sem plugin\')\n    ap.add_argument(\'--pasta\', nargs=\'+\', action=\'extend\', default=[], help=\'pastas da barra de baixo (NOME ou CAMINHO[=ROTULO])\')\n    ap.add_argument(\'--largura\', type=int, default=46, help=\'letras do nome (46 hi-res, 17 normal)\')\n    ap.add_argument(\'--so\', nargs=\'*\', default=None, help=\'so\\\' estas pastas (dentro da 1.a), e a raiz sem subpastas\')\n    a = ap.parse_args()\n    global CORRE, LARG_NOME\n    LARG_NOME = max(8, min(46, a.largura))\n    if not a.todos:\n        CORRE, onde = plugins_do_cartao(a.pastas[0])\n        if CORRE: print(\'plugins em %s: %s\' % (onde, \' \'.join(sorted(CORRE))))\n        else:\n            CORRE = PLUGINS_BOB\n            print(\'sem /BIN/BPLUGINS: uso a lista do Bob Fossil: \' + \' \'.join(sorted(CORRE)))\n    if a.so is not None:\n        # so\' as pastas pedidas; a raiz do cartao tambem (sem descer), para a lista de cima\n        r = a.pastas[0]\n        processa(r, a.fazer, True)\n        for nome in a.so:\n            p = os.path.join(r, nome)\n            if not os.path.isdir(p): print(\'pasta %s: nao existe\' % nome); continue\n            for raiz, subs, _ in os.walk(p):\n                subs[:] = [s for s in subs if not de_sistema(s, False)]\n                processa(raiz, a.fazer, False)\n    else:\n      for p in a.pastas:\n        for raiz, subs, _ in os.walk(p):\n            topo = os.path.normpath(raiz) == os.path.normpath(p)\n            subs[:] = [s for s in subs if not de_sistema(s, topo)]\n            processa(raiz, a.fazer, topo)\n    if a.pasta: escreve_pastas(a.pastas[0], a.pasta, a.fazer)\n    if not a.fazer: print(\'(nada foi escrito; repete com --fazer)\')\n\nif __name__ == \'__main__\':\n    main()\n',
}

import types
def corre(script, *args):
    nome = script[:-3]
    print('\n>>', script, ' '.join(args), flush=True)
    for m in ('maquina',):                       # o gera_nav.py faz "import maquina"
        if m not in sys.modules:
            mod = types.ModuleType(m); mod.__file__ = m + '.py'
            exec(compile(FONTES[m], m + '.py', 'exec'), mod.__dict__); sys.modules[m] = mod
    velho = sys.argv
    sys.argv = [script] + list(args)
    try:
        g = {'__name__': '__main__', '__file__': os.path.join(AQUI, script)}
        exec(compile(FONTES[nome], script, 'exec'), g)
    except SystemExit as e:
        if e.code not in (None, 0): sys.exit('%s parou: %s' % (script, e.code))
    finally:
        sys.argv = velho

# config.ini ao lado do cartao.py (opcional; o que vem na linha de comando ganha):
#   [pastas]            barra de baixo do navegador, por esta ordem (ate' 8)
#   DEMOS               nome da pasta (procura no cartao a menos funda com esse nome)
#   PT3 = MUSICA/PT3    rotulo (ate' 6 letras) = caminho dentro do cartao
#   [opcoes]
#   jogos = GAMES DEMOS pastas de jogos (o mesmo que --pastas): arruma-as, mete a maquina no nome e indexa-as
#                       ("jogos =" vazio: nenhuma; sem a linha: todas as da raiz menos as do sistema e FAVORITOS)
#   indexar = FAVORITOS MUSICA   pastas que so' indexa, sem mexer nos nomes ("tudo" = todas as do cartao)
#   normal = no         yes = nomes de 17 letras (navegador de 32 colunas)
import configparser
CFG = configparser.ConfigParser(allow_no_value=True, delimiters=('=',), comment_prefixes=('#', ';'))
CFG.optionxform = str
def le_config():
    f = os.path.join(AQUI, 'config.ini')
    if os.path.isfile(f):
        CFG.read(f, encoding='utf-8')
        print('config: %s' % f)

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('cartao')
    ap.add_argument('--fazer', action='store_true')
    ap.add_argument('--pastas', nargs='*', help='pastas de jogos (dentro do cartao)')
    ap.add_argument('--pasta', nargs='+', action='extend', default=[], help='pastas da barra de baixo do navegador')
    ap.add_argument('--normal', action='store_true', help='nomes de 17 letras (navegador de 32 colunas)')
    ap.add_argument('--so-indices', action='store_true', help="so' os indices do cartao todo, sem arrumar nem mudar nomes")
    ap.add_argument('--indexar', nargs='*', help="pastas que so' se indexam, sem mexer nos nomes (o mesmo que indexar = no config.ini)")
    a = ap.parse_args()
    if not os.path.isdir(a.cartao): sys.exit('nao existe: %s' % a.cartao)
    le_config()
    jogos_cfg = False
    if not a.pastas and CFG.has_option('opcoes', 'jogos'):
        a.pastas = CFG.get('opcoes', 'jogos').split(); jogos_cfg = True   # "jogos =" vazio = nenhuma
    if a.indexar is None and CFG.has_option('opcoes', 'indexar'):
        a.indexar = CFG.get('opcoes', 'indexar').split()
    if not a.normal and CFG.has_option('opcoes', 'normal'):
        a.normal = CFG.getboolean('opcoes', 'normal')
    if a.pastas:
        pastas = [os.path.join(a.cartao, p) for p in a.pastas]
    elif jogos_cfg:
        pastas = []
    else:
        pastas = [os.path.join(a.cartao, d) for d in sorted(os.listdir(a.cartao))
                  if os.path.isdir(os.path.join(a.cartao, d)) and d.upper() not in FORA and not d.startswith('.')]
    pastas = [p for p in pastas if os.path.isdir(p)]
    f = ['--fazer'] if a.fazer else []
    if a.so_indices:
        pastas = []; a.pastas = []; a.indexar = ['tudo']   # o gera_nav passa pelo cartao todo
        print('so\' os indices (sem arrumar nem mudar nomes)')
    elif not pastas and a.indexar:
        print('sem pastas de jogos; so\' indices em: %s' % ' '.join(a.indexar))
    else:
        if not pastas: sys.exit('nao encontrei pastas de jogos em %s (ou usa --so-indices / indexar = ...)' % a.cartao)
        print('pastas de jogos:', ', '.join(os.path.basename(p) for p in pastas), flush=True)
        for p in pastas: corre('maquina.py', p, *f)
        corre('arruma.py', *pastas, '--por-titulo', *f)
    if a.fazer:
        if not a.pasta and CFG.has_section('pastas'):   # sem --pasta: o config.ini
            for k, v in CFG.items('pastas'):
                a.pasta.append('%s=%s' % (v, k) if v else k)     # ROTULO = CAMINHO, ou so' NOME
            print('pastas da barra (config.ini): %s' % ' '.join(a.pasta))
        extra = (['--pasta'] + a.pasta if a.pasta else []) + (['--largura', '17'] if a.normal else [])
        so = [os.path.relpath(p, a.cartao) for p in pastas] + [x for x in (a.indexar or []) if x.lower() != 'tudo']
        if so and not any(x.lower() == 'tudo' for x in (a.indexar or [])):
            extra += ['--so'] + so                  # so' as pastas do "jogos" e do "indexar" (e a raiz)
        corre('gera_nav.py', a.cartao, '--fazer', *extra)
        print('\nFeito. Agora "Ejetar" antes de tirar o cartao.')
    else:
        print('\n(nada foi mudado: repete com --fazer; os indices so\' se fazem com --fazer)')

if __name__ == '__main__':
    main()
